(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.02-t*0.22)*18 + Math.sin(x*0.016+t*0.3)*12;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.025+sy*0.01+t*0.4)*8;
  const w2y = Math.cos(sy*0.025-sx*0.01-t*0.35)*8;
  const fx = sx+w2x, fy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*110, 80+Math.cos(t*0.4)*55, 0.075, 2.1, 0.9],
    [320+Math.cos(t*0.5)*110, 160+Math.sin(t*0.7)*55, 0.09, 1.8, 1.1],
    [240+Math.sin(t*0.3+2)*150, 120+Math.cos(t*0.5+1)*95, 0.055, 2.4, 0.8],
    [120+Math.cos(t*0.8+1)*90, 180+Math.sin(t*0.6+3)*65, 0.11, 1.6, 1.2],
    [360+Math.sin(t*0.4+4)*100, 60+Math.cos(t*0.9+2)*75, 0.065, 2.7, 0.7],
    [240+Math.cos(t*0.35+5)*130, 200+Math.sin(t*0.55)*85, 0.085, 2.0, 1.0],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+2)*50, 0.1, 1.9, 1.15],
    [400+Math.cos(t*0.55+1)*80, 220+Math.sin(t*0.75+4)*60, 0.07, 2.5, 0.85]
  ];
  let aS=0, iS=0, cross=0;
  for(let i=0;i<src.length;i++){
    const [sX,sY,f,sp,w]=src[i];
    const d=Math.sqrt((fx-sX)**2+(fy-sY)**2);
    const a=Math.sin(d*f-t*sp);
    const ih=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS+=a*w; iS+=ih*w;
    for(let j=i+1;j<src.length;j++){
      const [sX2,sY2,f2,sp2]=src[j];
      const d2=Math.sqrt((fx-sX2)**2+(fy-sY2)**2);
      cross+=Math.sin((d*f+d2*f2)*0.5-t*(sp+sp2)*0.4)*0.15;
    }
  }
  const n=src.length;
  aS/=n; iS/=n;
  const bg=(Math.sin(fx*0.035+fy*0.022+t*0.75)+Math.sin(fx*0.028-fy*0.038+t*1.05))/2
    +Math.sin((fx+fy)*0.11+t*2.3)*0.2+Math.sin((fx-fy)*0.09-t*1.9)*0.2
    +Math.sin(fx*0.07*fy*0.0001+t*0.5)*0.15;
  const dist=Math.sqrt((fx-cx)**2+(fy-cy)**2), ang=Math.atan2(fy-cy,fx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3.5-t*1.4)+Math.sin(dist*0.035+ang*4.5-t*1.1))*0.35
    +Math.sin(dist*0.08-ang*2-t*2.2)*0.15;
  const micro=(Math.sin(fx*0.4+t*3)*Math.sin(fy*0.4-t*2.5)+Math.sin((fx*fy)*0.001+t))*0.12;
  const raw=aS-iS*0.65+bg*0.25+spiral+cross+micro;
  const reaction=Math.tanh(raw*2.0);
  const cell=Math.tanh((Math.sin(fx*0.14)*Math.sin(fy*0.14)+Math.sin((fx+fy)*0.09+t)*0.5)*1.4)*0.25;
  const blend=reaction*0.7+cell*0.3;
  const edge=Math.abs(reaction);
  const glow=edge>0.65?Math.pow((edge-0.65)/0.35,2)*0.4:0;
  const v=Math.max(0,Math.min(1,blend*0.5+0.5+glow));
  const pal=[
    [5,12,52],[12,45,95],[18,85,125],[25,135,135],
    [140,175,80],[210,185,55],[215,130,65],[175,65,70],
    [120,30,65],[60,18,55],[5,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.78+Math.sin(reaction*Math.PI)*0.22;
  const eMul=edge>0.7?1.12:1.0;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f+glow*60)*lum*eMul)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f+glow*40)*lum*eMul)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f+glow*30)*lum*eMul)|0
  ];
}
